// A pretend post office on this computer, so fetch never needs the internet.
// openPostOffice() starts a small web server on a free port and returns { url, close }.
import { createServer } from "node:http";
import { once } from "node:events";

function reply(res, status, type, body) {
  res.writeHead(status, { "content-type": type });
  res.end(body);
}
const json = (res, status, data) => reply(res, status, "application/json", JSON.stringify(data));

export async function openPostOffice() {
  let flakyCalls = 0;
  const server = createServer((req, res) => {
    let body = "";
    req.on("data", (chunk) => (body += chunk));
    req.on("end", () => {
      const url = new URL(req.url, "http://post.office");
      switch (url.pathname) {
        case "/seats":   return json(res, 200, { play: "Hamlet", free: ["F7", "F8"] });
        case "/missing": return json(res, 404, { error: "no such show" });
        case "/oops":    return reply(res, 500, "text/html", "<html><body><h1>Server error</h1></body></html>");
        case "/slow":    return setTimeout(() => json(res, 200, { late: true }), 2000);
        case "/flaky":   return ++flakyCalls < 3 ? json(res, 503, { error: "busy" }) : json(res, 200, { play: "Hamlet" });
        case "/search":  return json(res, 200, { query: Object.fromEntries(url.searchParams) });
        case "/echo": {
          const type = (req.headers["content-type"] || "(none)").split(";")[0];
          const fields = type === "multipart/form-data" ? [...body.matchAll(/name="([^"]+)"/g)].map((m) => m[1]) : undefined;
          return json(res, 200, { method: req.method, type, body: fields ? undefined : body, fields });
        }
        default: return reply(res, 404, "text/plain", "Not found");
      }
    });
  });
  server.listen(0, "127.0.0.1");               // port 0: any free port
  await once(server, "listening");
  return {
    url: "http://127.0.0.1:" + server.address().port,
    close: () => { server.closeAllConnections(); server.close(); },
  };
}

// The address of a post office that has just closed for good: nothing answers there.
export async function closedAddress() {
  const office = await openPostOffice();
  office.close();
  return office.url;
}

