import { openPostOffice } from "./lib/post-office.js";

async function getWithRetry(url, tries = 3) {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(url);
    const wait = 100 * 2 ** (attempt - 1);
    const again = !res.ok && res.status >= 500 && attempt < tries;
    console.log(`attempt ${attempt}: status ${res.status}`, res.ok ? "-> done" : again ? `-> wait ${wait} ms, try again` : "-> give up");
    if (res.ok) return res.json();
    if (!again) throw new Error(`HTTP ${res.status}`);
    await new Promise((resolve) => setTimeout(resolve, wait));
  }
}

const office = await openPostOffice();
console.log(await getWithRetry(office.url + "/flaky"));
await getWithRetry(office.url + "/missing").catch((err) => console.log("failed:", err.message));
