// A tiny pretend internet for this chapter's browser pages, all on this computer.
//
//   node stage/theater.cjs page.html [page.actions.json]
//
// 1. Starts one small web server (node:http) on a free local port. It plays two websites:
//      http://theater.test/     serves the files in this folder (the pages), plus a few /api/ addresses
//      http://boxoffice.test/   another site with its own API, so cross-site (CORS) rules really apply
// 2. Opens the page in headless Chromium, which is told to send every request to that server
//    (a proxy setting), so the addresses above work without the internet.
// 3. Prints the browser console: console.log/info -> stdout; console.warn/error, the browser's own
//    red messages and uncaught errors -> stderr. Exit code 1 if the page threw an uncaught error.
// Optional actions run in order after the page loads, for example:
//   [{"click": "#seat"}, {"type": ["#name", "Ada"]}, {"key": "Tab"}, {"reload": true}, {"newtab": "other.html"}]
const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");
const { chromium } = require("playwright");

const ROOT = process.cwd();
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8", ".txt": "text/plain; charset=utf-8" };

function send(res, status, type, body, extra) {
  res.writeHead(status, Object.assign({ "content-type": type }, extra || {}));
  res.end(body);
}

function theater(req, res, url, body) {
  if (url.pathname === "/favicon.ico") return send(res, 204, "text/plain", "");
  if (url.pathname === "/api/seats") return send(res, 200, TYPES[".json"], JSON.stringify({ play: "Hamlet", free: ["F7", "F8"] }));
  if (url.pathname === "/api/missing") return send(res, 404, TYPES[".json"], JSON.stringify({ error: "no such show" }));
  if (url.pathname === "/api/echo") {
    return send(res, 200, TYPES[".json"], JSON.stringify({ method: req.method, type: (req.headers["content-type"] || "").split(";")[0], body }));
  }
  const file = path.join(ROOT, decodeURIComponent(url.pathname));
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) return send(res, 404, TYPES[".txt"], "Not found");
  const delay = Number(url.searchParams.get("delay") || 0);   // ?delay=300 answers 300 ms late (a slow script)
  setTimeout(() => send(res, 200, TYPES[path.extname(file)] || "application/octet-stream", fs.readFileSync(file)), delay);
}

function boxoffice(req, res, url) {
  const seats = JSON.stringify({ play: "Hamlet", free: ["F7", "F8"] });
  if (url.pathname === "/seats") return send(res, 200, TYPES[".json"], seats);   // no CORS header
  if (url.pathname === "/open-seats") return send(res, 200, TYPES[".json"], seats, { "access-control-allow-origin": "http://theater.test" });
  return send(res, 404, TYPES[".txt"], "Not found");
}

const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    const url = new URL(req.url, "http://" + req.headers.host);
    if (url.hostname === "theater.test") return theater(req, res, url, body);
    if (url.hostname === "boxoffice.test") return boxoffice(req, res, url);
    send(res, 502, TYPES[".txt"], "Only theater.test and boxoffice.test exist here");
  });
});

(async () => {
  const [page0, actionsFile] = process.argv.slice(2);
  const actions = actionsFile ? JSON.parse(fs.readFileSync(actionsFile, "utf8")) : [];
  server.listen(0, "127.0.0.1");
  await new Promise((r) => server.once("listening", r));
  const browser = await chromium.launch({ proxy: { server: "http://127.0.0.1:" + server.address().port } });
  const ctx = await browser.newContext({ viewport: { width: 800, height: 600 }, timezoneId: "UTC", locale: "en-US" });
  let threw = false;
  const watch = (page) => {
    page.on("console", (m) => { const t = m.type(), line = m.text() + "\n"; if (t === "error" || t === "warning") process.stderr.write(line); else process.stdout.write(line); });
    page.on("pageerror", (e) => {
      threw = true;
      const msg = String(e.message).replace(/^Uncaught\s+/, ""), name = String(e.name || "Error").replace(/^Uncaught\s+/, "");
      process.stderr.write("Uncaught " + (/^[A-Za-z]*Error\b/.test(msg) ? msg : name + ": " + msg) + "\n");
    });
    return page;
  };
